/**
 * Strict Action Plan Schema & Runtime Validator for Handsfree
 * Uses Zod to strictly validate plans generated by local Qwen2.5-1.5B-Instruct.
 */

import { z } from 'zod';
import { ActionPlan } from '../../types/ai';

// Safe URL validator: Only http and https protocols allowed
const SafeUrlSchema = z
  .string()
  .trim()
  .refine(
    (val) => {
      try {
        const parsed = new URL(val);
        return parsed.protocol === 'http:' || parsed.protocol === 'https:';
      } catch {
        return false;
      }
    },
    { message: 'URL must be a valid http or https address' }
  );

// Target locator
export const ActionTargetSchema = z
  .object({
    role: z.string().trim().max(50).optional(),
    name: z.string().trim().max(120).optional(),
    text: z.string().trim().max(120).optional(),
    id: z.string().trim().max(80).optional(),
    ordinalIndex: z.number().int().min(0).max(50).optional(),
  })
  .strict();

// 1. Navigate Step
const NavigateStepSchema = z
  .object({
    action: z.literal('navigate'),
    url: SafeUrlSchema,
  })
  .strict();

// 2. Click Step
const ClickStepSchema = z
  .object({
    action: z.literal('click'),
    target: ActionTargetSchema,
  })
  .strict();

// 3. Fill Step
const FillStepSchema = z
  .object({
    action: z.literal('fill'),
    target: ActionTargetSchema,
    text: z.string().max(1000),
  })
  .strict();

// 4. Press Key Step
const PressKeyStepSchema = z
  .object({
    action: z.literal('press_key'),
    key: z
      .string()
      .trim()
      .max(20)
      .transform((k) => {
        // Standardize keys (e.g. ENTER -> Enter)
        if (k.toUpperCase() === 'ENTER') return 'Enter';
        if (k.toUpperCase() === 'ESCAPE' || k.toUpperCase() === 'ESC') return 'Escape';
        if (k.toUpperCase() === 'TAB') return 'Tab';
        if (k.toUpperCase() === 'SPACE') return ' ';
        return k;
      }),
  })
  .strict();

// 5. Scroll Step
const ScrollStepSchema = z
  .object({
    action: z.literal('scroll'),
    direction: z.enum(['up', 'down', 'top', 'bottom']),
    amount: z.number().min(10).max(3000).optional(),
  })
  .strict();

// 6. Select Step
const SelectStepSchema = z
  .object({
    action: z.literal('select'),
    target: ActionTargetSchema,
    option: z.string().trim().max(100),
  })
  .strict();

// 7. Wait Step (bounded to 100ms - 10,000ms)
const WaitStepSchema = z
  .object({
    action: z.literal('wait'),
    durationMs: z.number().int().min(50).max(10000),
  })
  .strict();

// 8. Extract Text Step
const ExtractTextStepSchema = z
  .object({
    action: z.literal('extract_text'),
    target: ActionTargetSchema.optional(),
    query: z.string().trim().max(100).optional(),
  })
  .strict();

// 9. Compare Items Step
const CompareItemsStepSchema = z
  .object({
    action: z.literal('compare_items'),
    items: z.array(z.string().trim().max(100)).min(2).max(10),
  })
  .strict();

// 10. Go Back Step
const GoBackStepSchema = z
  .object({
    action: z.literal('go_back'),
  })
  .strict();

// 11. Clarify Step
const ClarifyStepSchema = z
  .object({
    action: z.literal('clarify'),
    question: z.string().trim().min(3).max(250),
  })
  .strict();

// Union of registered steps
export const ActionPlanStepSchema = z.discriminatedUnion('action', [
  NavigateStepSchema,
  ClickStepSchema,
  FillStepSchema,
  PressKeyStepSchema,
  ScrollStepSchema,
  SelectStepSchema,
  WaitStepSchema,
  ExtractTextStepSchema,
  CompareItemsStepSchema,
  GoBackStepSchema,
  ClarifyStepSchema,
]);

// Full Action Plan Schema
export const ActionPlanZodSchema = z
  .object({
    status: z.enum(['ready', 'clarification_required', 'unsupported', 'page_inspection_required']),
    reason: z.string().trim().max(500),
    steps: z.array(ActionPlanStepSchema).max(10),
    requires_confirmation: z.boolean().default(false),
    clarification_question: z.string().trim().nullable().default(null),
  })
  .strict();

export class ActionPlanValidator {
  /**
   * Validates and returns parsed ActionPlan, or throws structured error
   */
  public static validate(data: unknown): ActionPlan {
    const parsed = ActionPlanZodSchema.parse(data);
    return parsed as ActionPlan;
  }

  /**
   * Safe parse that returns success flag and error details
   */
  public static safeValidate(data: unknown): {
    success: boolean;
    plan?: ActionPlan;
    error?: string;
  } {
    const result = ActionPlanZodSchema.safeParse(data);
    if (result.success) {
      return { success: true, plan: result.data as ActionPlan };
    }
    const issues = result.error.issues || (result.error as any).errors || [];
    const formattedError = issues
      .map((e: any) => `${e.path.join('.') || 'root'}: ${e.message}`)
      .join('; ');
    return { success: false, error: formattedError };
  }
}
